/**
 * Skill Template Workflow Modules
 *
 * This file is generated by splitting the legacy monolithic
 * templates file into workflow-focused modules.
 */
import type { SkillTemplate } from '../types.js';
import { XIRANG_PHILOSOPHY } from '../fragments/xirang-fragments.js';
import {
  SUBAGENT_QUALITY_EXECUTION_MODEL,
  type QualityExecutionModel,
} from './quality-execution-model.js';

const ARCHIVE_COMMIT_MESSAGE_REFERENCE_PATH = 'references/archive-commit-message.md';
const BOUNDARY_COMMIT_MESSAGE_REFERENCE_PATH = 'references/boundary-commit-message.md';
const MERGE_SUMMARY_MESSAGE_REFERENCE_PATH = 'references/merge-summary-message.md';
const ARCHIVE_COMMIT_MESSAGE_SHARED_PATH = '.xirang/references/xirang-archive-commit-message.md';
const BOUNDARY_COMMIT_MESSAGE_SHARED_PATH = '.xirang/references/xirang-boundary-commit-message.md';
const MERGE_SUMMARY_MESSAGE_SHARED_PATH = '.xirang/references/xirang-merge-summary-message.md';

const BOUNDARY_COMMIT_MESSAGE_REFERENCE = `
# Boundary Commit Message Template

Use this built-in format when \`git.commitMessage.boundary\` is not configured.

Subject:

\`\`\`text
<type>(<scope>): <English subject>
\`\`\`

Body:

\`\`\`text
## Why
[Business context] <why from proposal.md>
[Technical decision] <decision from design.md when present>

## Changes
- \`<file-path>\`: <why this file changed>
\`\`\`

Footer:

\`\`\`text
Implementation: <base>..<head> (carried by <commits>)
\`\`\`

Rules:
- Build \`## Why\` from the archived \`proposal.md\` and \`design.md\` (when present).
- Build \`## Changes\` from \`git diff --name-only <base>..<head>\` and reconcile the actual file list with archived goal-level intent in \`tasks.md\` and the archived Semantic Delta units.
- List all files from the diff; if a file is not mentioned in archived artifacts, state that explicitly.
- The \`<base>\` is the prior change boundary (prior archive/boundary commit); the agent infers it from git history.
- The \`Implementation:\` footer lists the effective diff range and the commits carrying that diff (including \`wip: opt-*\` checkpoint commits and any just-created normal implementation commit).
- Use \`git commit -F -\` to pass the message.
- Always create this commit with \`git commit --allow-empty\`; it may be intentionally empty when all implementation diff is carried by checkpoint commits.
`.trim();

const ARCHIVE_COMMIT_MESSAGE_REFERENCE = `
# Archive Commit Message Template

Use this built-in format when \`git.commitMessage.archive\` is not configured.

Subject:

\`\`\`text
docs(<change-name>): Archive change artifacts
\`\`\`

Body:

\`\`\`text
## Why
[Business context] <why this archive commit is needed>

## Changes
- \`<file-path>\`: <why this archived/synced path must be committed>
\`\`\`

Rules:
- Include only archive/synced paths selected for the archive commit.
- Keep non-archive dirty changes out of the commit.
- Pass the message through \`git commit -F -\`.
`.trim();

const MERGE_SUMMARY_MESSAGE_REFERENCE = `
# Merge Summary Message Template

Use this built-in format when \`git.commitMessage.merge\` is not configured.

Subject:

\`\`\`text
<type>(<scope>): <English subject>
\`\`\`

Body:

\`\`\`text
## Why
[Business context] <why from proposal.md>
[Technical decision] <decision from design.md when present>

## Changes
- \`<file-path>\`: <why this file changed>
\`\`\`

Rules:
- Build the summary from the archived \`proposal.md\`, \`design.md\`, \`tasks.md\`, and the archived Semantic Delta units.
- Use \`git commit -F -\` for no-ff merge commits and squash commits that require a message.
- Do not generate this message for \`ff-only\` merges.
`.trim();

function buildArchiveFullQualityContract(_executionModel: QualityExecutionModel): string {
  return `   Review the shared Apply/Quality references only when status identifies an outstanding obligation. A passing full-change Review must be recorded in .quality.json and bind an existing Git commit. The main Agent records either delivered Opt opinions bound to baseCommit/resultCommit or a non-empty not_performed reason, then decides from risk whether incremental Review or mandatory supplemental Review is needed. Only the main Agent writes Seal, declaring canRun and testsExpectedToPass for an existing commit. The CLI does not run tests, compare HEAD/workspace freshness or make these judgments. Preserve legacy Quality files unchanged. Do not run a completion review or modify the record during Archive; its Quality gate only checks that the Seal commit object exists.`;
}

function buildAgentGitFlowStep(): string {
  return `   The agent continues the post-archive git flow. First handle the implementation boundary before Xirang/docs archive artifacts. If uncommitted real project implementation changes remain, create a normal implementation commit that contains only those changes. Then always create a semantic boundary commit with \`git commit --allow-empty\`; this boundary commit may be intentionally empty when the effective implementation diff is already carried by retained \`wip: opt-*\` checkpoint commits. If \`git.commitMessage.boundary\` is set, read that project-relative path; otherwise read the project-root file \`${BOUNDARY_COMMIT_MESSAGE_SHARED_PATH}\`. Use that template to build the boundary commit message and run \`git commit -F -\` for the boundary commit. If \`git.commitMessage.archive\` is set, read that project-relative path; otherwise read the project-root file \`${ARCHIVE_COMMIT_MESSAGE_SHARED_PATH}\`. Use that template before creating the Xirang/docs archive commit, add only archive/synced paths, and run \`git commit -F -\`. If a merge or squash commit message is needed, prepare it from the configured or built-in merge template. If \`git.commitMessage.merge\` is set, read that project-relative path; otherwise read the project-root file \`${MERGE_SUMMARY_MESSAGE_SHARED_PATH}\`.

   Apply the retained isolation metadata after archive commits are complete. Map the projected strategy to \`git merge --no-ff\`, \`git merge --ff-only\`, or \`git merge --squash\`. For \`method: "branch"\`, switch to \`originalBranch\`, then merge \`branchName\` with the projected strategy. For \`method: "worktree"\`, keep commits in \`worktreePath\`; before merging, verify that \`sourceRoot\` is on \`originalBranch\`, then run the projected merge from \`sourceRoot\` using \`git -C <sourceRoot>\`. The agent MUST NOT reset, clean, stash, or commit unrelated source-workspace changes. After a successful merge, require the Apply worktree to be clean, run \`git worktree remove <worktreePath>\` from \`sourceRoot\`, and only then delete \`branchName\` when \`git.branch.deleteAfterArchive\` is true and \`git branch --merged\` confirms it is merged. For \`method: "none"\`, do not switch, merge, remove a worktree, or delete the current branch. Stop and report the retained metadata/current state mismatch instead of guessing. Build paths with \`path.join()\`, \`path.resolve()\`, and \`path.normalize()\`.`;
}

function buildArchiveInstructions(
  inputLine: string,
  executionModel: QualityExecutionModel
): string {
  return `Archive a completed change in the Xirang change workflow.

${XIRANG_PHILOSOPHY}

For workflow-managed writes, read the resolved file definition before its instruction and template, and MUST NOT copy definitions, config projections, or reasoning into artifacts.

**Input**: ${inputLine}

Before archiving, run \`xirang config project --json\` and consume git policy from its normalized project config: \`git.commitMessage.archive\`, \`git.commitMessage.merge\`, \`git.merge.strategy\`, and \`git.branch.deleteAfterArchive\`; do not parse raw YAML inside the skill.

**Steps**

1. **Select change**
   If no clear change name is provided, run \`xirang list --json\`, show active changes with schema, and ask. Do not guess. Read \`.apply-isolation.json\` before running the archive CLI and retain its validated \`method\`, \`branchName\`, \`originalBranch\`, \`worktreePath\`, and \`sourceRoot\` values because the CLI moves the active change directory.

2. **Unified Quality Gate**
   Require a recorded passing full-change Review, explicit Opt disposition and a successful Seal. No latest incremental or supplemental Review may remain failed. For Archive's Quality sub-gate, the Seal commit must exist in Git; HEAD/workspace differences and Quality JSON commit status are irrelevant. Keep the current Quality status projection for the final summary. Preserve unsupported legacy records unchanged.

2.5. **Complete Required Quality Evidence**

${buildArchiveFullQualityContract(executionModel)}

3. **Check artifact completion status**
   Run \`xirang status --change "<name>" --json\`. Warn and confirm before proceeding if any artifact is not \`done\`.

4. **Check task completion status**
   Read \`tasks.md\`; warn and confirm before proceeding if incomplete goal checkboxes remain. Missing goals are not a task-related blocker.

5. **Assess delta sync state**
   If any of \`.xirang/changes/<name>/{metamodel,elements,relationships,views}/\` is non-empty, assess whether sync is required. The archive CLI performs the quality gate, sync, and move-to-archive; do not duplicate sync writes manually.

6. **Run archive CLI**
   Run \`xirang archive "<change-name>"\` after the Seal commit exists. CLI checks the Seal commit object, performs the independent Sync/validation/task gates, moves the Change and prints the Git handoff reminder; it does not create commits, compare HEAD/workspace, alter Quality JSON, merge/switch/delete branches, or remove worktrees.

7. **Git handoff**
   Read the archive CLI output and projected Git policy from \`xirang config project --json\`. Use the retained Quality status for Review, Opt disposition and Seal evidence; do not infer that CLI ran tests or made a Git commit.

8. **Agent git flow**
${buildAgentGitFlowStep()}

9. **Display summary**
   Include change, schema, archive location, quality gate result, Semantic Model sync result, agent-owned git follow-up status, Merge Strategy and cleanup responsibility. Distinguish full-change Review, additional incremental or supplemental Reviews actually performed, main reasons for omitted optional Review, actual test evidence and Seal commit assessment. Disclose abandoned optimization attempts/reasons/treatment and remaining warnings. Do not report that CLI created an archive commit, performed a merge or deleted a feature branch.

**Output On Success**

\`\`\`
## Archive Complete

**Change:** <change-name>
**Schema:** <schema-name>
**Archived to:** .xirang/changes/archive/YYYY-MM-DD-<name>/
**Quality Gate:** valid Seal commit exists; Archive independently completed Sync, validation and task gates
**Semantic Model:** ✓ Synced into \`.xirang/model/\`, rewriting only the units the Semantic Delta affects, all-or-nothing (or "No deltas" or "Sync gate bypassed with --no-sync")
**Agent Git Follow-up:** <completed / pending with reason>
**Merge Strategy:** <git.merge.strategy>
**Cleanup Responsibility:** <agent>

Archive completed after satisfying the unified quality gate.
\`\`\`

**Guardrails**
- Always prompt for change selection if not provided
- Prioritize the standard quality gate; only pass \`--no-verify\` to the archive CLI when the user explicitly requests it (the CLI provides its own confirmation prompt)
- Show which baseline and scoped Review evidence was reused or newly obtained, and distinguish main-agent applicability/risk decisions from actual independent Review
- In \`core\`, use \`xirang sync "<change-name>"\` rather than manual inline sync
- If any of \`.xirang/changes/<name>/{metamodel,elements,relationships,views}/\` is non-empty, always run the shared sync assessment before moving the change directory`;
}

export function createArchiveChangeSkillTemplateForExecutionModel(
  executionModel: QualityExecutionModel = SUBAGENT_QUALITY_EXECUTION_MODEL
): SkillTemplate {
  return {
    name: 'xirang-archive-change',
    description:
      'Archive a completed change in the Xirang change workflow. Use when the user wants to finalize and archive a completed change after implementation is complete.',
    instructions: buildArchiveInstructions(
      'Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.',
      executionModel
    ),
    license: 'MIT',
    compatibility: 'Requires xirang CLI.',
    metadata: { author: 'xirang', version: '1.0' },
    referenceFiles: [
      {
        path: ARCHIVE_COMMIT_MESSAGE_REFERENCE_PATH,
        content: ARCHIVE_COMMIT_MESSAGE_REFERENCE,
      },
      {
        path: BOUNDARY_COMMIT_MESSAGE_REFERENCE_PATH,
        content: BOUNDARY_COMMIT_MESSAGE_REFERENCE,
      },
      {
        path: MERGE_SUMMARY_MESSAGE_REFERENCE_PATH,
        content: MERGE_SUMMARY_MESSAGE_REFERENCE,
      },
    ],
  };
}

export function getArchiveChangeSkillTemplate(): SkillTemplate {
  return createArchiveChangeSkillTemplateForExecutionModel();
}
